mapper.update:
UPDATE t_payment_task_lease
SET lock_expires_at = TIMESTAMPADD(SECOND, #{leaseSeconds}, NOW()),
    updated_at = NOW()
WHERE task_code = #{taskCode}
  AND lock_owner = #{lockOwner}
  AND lock_expires_at > NOW()

UPDATE t_payment_task_lease
SET lock_owner = NULL,
    lock_expires_at = NULL,
    updated_at = NOW()
WHERE task_code = #{taskCode}
  AND lock_owner = #{lockOwner}
